397		\lean{MIPStarRE.QPBT.consistencyDefect_postprocess_le}
398		\leanok
399		\uses{def:consistency, def:bracket}
400		Suppose $A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$. Then for any function $f$ on the outcome set,
401		\[
402			A^x_{[f(\cdot)=b]} \ot \Id_B \simeq_\delta \Id_A \ot B^x_{[f(\cdot)=b]}\,.
403		\]
404	\end{lemma}
405	\begin{proof}
406		\leanok
407		\uses{def:distance-state-quadratic-form,
408			lem:distance-consistency-term, lem:distance-point-defect,
409			def:distance-left-placed-measurement,
410			def:distance-right-placed-measurement,
411			lem:distance-placed-product-qform,
412			lem:distance-postprocess-overlap}
413		Stated in the source without proof; it is Fact 4.26 of \cite{Natarajan2018NEEXP}. Every off-diagonal pair $(b, b')$ with $b \ne b'$ of the post-processed families pulls back to pairs $(a, a')$ with $f(a) = b \ne b' = f(a')$, and in particular $a \ne a'$. Coarse-graining therefore only merges terms of the off-diagonal sum, so the post-processed off-diagonal mass is at most the original one.
