416	The state-dependent distance is the right tool for reasoning about the closeness of measurement operators in a strategy. The following lemma converts joint consistency with a single projective measurement into an approximate commutation relation.
417	
418	\begin{lemma}[Approximate commutation from joint consistency]\label{lem:commutation-analysis}
419		\lean{MIPStarRE.QPBT.opDistSq_commutator_le}
420		\leanok
421		\uses{def:povm-distance, def:povm-conventions}
422		Let $\{A^x_{a,\,b}\}$, $\{B^x_{a,\,b,\,c}\}$, $\{C^x_{a,\,c}\}$ be POVMs. Suppose $\{B^x_{a,\,b,\,c}\}$ is projective, and
423		\begin{align*}
424			A^x_{a,\,b} \ot \Id_B &\approx_\delta \Id_A \ot B^x_{a,\,b}\,,\\
425			C^x_{a,\,c} \ot \Id_B &\approx_\delta \Id_A \ot B^x_{a,\,c}\,,
426		\end{align*}
427		where $B^x_{a,\,b} = \sum_c B^x_{a,\,b,\,c}$ and $B^x_{a,\,c} = \sum_b B^x_{a,\,b,\,c}$ are the marginals of Definition~\ref{def:povm-conventions}. Then the following approximate commutation relation holds:
428		\[
429			[A^x_{a,\,b},\, C^x_{a,\,c}] \ot \Id_B \approx_\delta 0\,.
430		\]
431	\end{lemma}
432	\begin{proof}
433		\leanok
434		\uses{fact:add-a-proj, fact:triangle,
435			lem:distance-left-fiber-contraction,
436			lem:distance-right-fiber-contraction,
437			lem:distance-joint-marginal-product,
438			lem:distance-joint-marginal-product-rev,
439			lem:distance-opposite-placements-commute, lem:distance-reindex,
440			lem:distance-congr, lem:distance-congr-sub,
441			def:distance-swap-last, lem:distance-swap-last-inverse,
442			lem:distance-symmetry}
443		Applying Lemma~\ref{fact:add-a-proj} to $C^x_{a,\,c} \ot \Id_B \approx_\delta \Id_A \ot B^x_{a,\,c}$ with the multiplier family $\{A^x_{a,\,b} \ot \Id_B\}$, we have
444		\begin{equation}\label{eq:commutation-analysis-1}
445			A^x_{a,\,b}\, C^x_{a,\,c} \ot \Id_B \approx_\delta A^x_{a,\,b} \ot B^x_{a,\,c}\,.
446		\end{equation}
447		Similarly, applying Lemma~\ref{fact:add-a-proj} to $A^x_{a,\,b} \ot \Id_B \approx_\delta \Id_A \ot B^x_{a,\,b}$ with the multiplier family $\{\Id_A \ot B^x_{a,\,c}\}$, and using that $\{B^x_{a,\,b,\,c}\}$ is projective,
448		\begin{equation}\label{eq:commutation-analysis-2}
449			A^x_{a,\,b} \ot B^x_{a,\,c} \approx_\delta \Id_A \ot B^x_{a,\,c}\, B^x_{a,\,b} = \Id_A \ot B^x_{a,\,b,\,c}\,.
450		\end{equation}
451		Combining \eqref{eq:commutation-analysis-1} and \eqref{eq:commutation-analysis-2} via Lemma~\ref{fact:triangle},
452		\begin{equation}\label{eq:commutation-analysis-3}
453			A^x_{a,\,b}\, C^x_{a,\,c} \ot \Id_B \approx_\delta \Id_A \ot B^x_{a,\,b,\,c}\,.
454		\end{equation}
455		A symmetric argument gives
456		\begin{equation}\label{eq:commutation-analysis-4}
457			C^x_{a,\,c}\, A^x_{a,\,b} \ot \Id_B \approx_\delta \Id_A \ot B^x_{a,\,b,\,c}\,.
458		\end{equation}
459		The claim follows by subtracting \eqref{eq:commutation-analysis-3} and \eqref{eq:commutation-analysis-4}.
460	\end{proof}
